package cli

import "github.com/spf13/cobra"

// addJSONFlag registers --json locally on a command that can render its result
// as a machine-readable document.
//
// Local, never persistent. A persistent --json would be inherited — and
// silently ignored — by every side-effecting verb, and cobra offers no way to
// hide a persistent flag from a subset of children. Accepting a flag and
// honouring it have to be the same act, so the one-line registration sits on
// exactly the commands that honour it, and `harnaas <verb> --json` fails as an
// unknown flag everywhere else. Read it back with jsonRequested.
func addJSONFlag(cmd *cobra.Command) {
	cmd.Flags().Bool("json", false, "Write the result to stdout as a JSON document")
}

// jsonRequested reports whether --json was requested on cmd.
//
// A command that never registered the flag answers "not requested" rather than
// panicking: the lookup failing means the flag is undeclared on this command
// tree, which is a truthful no. That lets shared rendering helpers ask
// unconditionally instead of every caller tracking whether its command has a
// JSON view.
func jsonRequested(cmd *cobra.Command) bool {
	requested, err := cmd.Flags().GetBool("json")
	return err == nil && requested
}

package cli

import (
	"encoding/json"
	"fmt"

	"github.com/spf13/cobra"
)

// The output contract, stated once for every command in this package.
//
// stdout carries the result and nothing else: the text a person reads, or —
// under --json — the document alone, so `harnaas … --json | jq` never chokes on
// a progress line that happened to land mid-stream. stderr carries everything
// advisory: progress, warnings, and any explanation of what the command chose
// to do. Both are reached through the command's own writers, never through the
// process globals, so a test can capture them.
//
// Cobra's Print* helpers write to OutOrStderr — stderr in production — and so
// would send a command's result to the wrong stream. forbidigo rejects them.

// printJSON writes v to stdout as the command's entire result.
//
// Indented, because a person reads this output as often as a script does.
// HTML left unescaped, because Go's default would rewrite an ampersand or an
// angle bracket in a path, an asset id or a source ref into an escape that no
// consumer asked for. Newline-terminated, so the document ends the stream
// cleanly for a line-oriented reader.
func printJSON(cmd *cobra.Command, v any) error {
	enc := json.NewEncoder(cmd.OutOrStdout())
	enc.SetIndent("", "  ")
	enc.SetEscapeHTML(false)
	if err := enc.Encode(v); err != nil {
		return fmt.Errorf("encode json output: %w", err)
	}
	return nil
}

// advisef writes progress, warning or explanatory text to stderr. None of it is
// part of the result, so it stays off stdout whether or not --json was
// requested. The caller supplies the trailing newline.
func advisef(cmd *cobra.Command, format string, args ...any) {
	fmt.Fprintf(cmd.ErrOrStderr(), format, args...)
}

package cli

import (
	"go/ast"
	"go/parser"
	"go/token"
	"strings"
	"testing"

	"github.com/spf13/cobra"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// newLeafCmd builds a subcommand that does nothing, for tests that care about
// how the tree is wired rather than what a command does.
func newLeafCmd(use string) *cobra.Command {
	return &cobra.Command{
		Use:   use,
		Short: "a subcommand used only by the wiring tests",
		Args:  cobra.NoArgs,
		RunE:  func(*cobra.Command, []string) error { return nil },
	}
}

// TestRootDeclaresNoPersistentFlags is the guard on the rule that gives --json
// its meaning: nothing is inherited, so a flag a command accepts is a flag that
// command honours. Adding a persistent flag here — however convenient — would
// make every future verb silently accept it.
func TestRootDeclaresNoPersistentFlags(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()
	// Cobra registers --help and --version lazily, on Flags() rather than
	// PersistentFlags(); force that to happen so the assertion is made against
	// a fully initialized command.
	root.InitDefaultHelpFlag()
	root.InitDefaultVersionFlag()

	var declared []string
	root.PersistentFlags().VisitAll(func(f *pflagFlag) { declared = append(declared, f.Name) })

	assert.Empty(t, declared,
		"the root must declare no persistent flags; register a flag locally on each command that honours it")
}

// TestJSONFlagIsUnknownOnACommandThatDoesNotDeclareIt is the other half of the
// same rule, observed from the outside: --json is only accepted where it is
// registered, and elsewhere it fails loudly instead of being ignored.
func TestJSONFlagIsUnknownOnACommandThatDoesNotDeclareIt(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()
	renders := newLeafCmd("renders")
	addJSONFlag(renders)
	addCommand(root, renders, groupAssets)
	addCommand(root, newLeafCmd("acts"), groupSetup)

	tests := []struct {
		name    string
		args    []string
		wantErr string
	}{
		{"the command that declares it accepts it", []string{"renders", "--json"}, ""},
		{"a sibling that does not declare it rejects it", []string{"acts", "--json"}, "unknown flag: --json"},
		{"the root rejects it too", []string{"--json"}, "unknown flag: --json"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			root := NewRootCmd()
			renders := newLeafCmd("renders")
			addJSONFlag(renders)
			addCommand(root, renders, groupAssets)
			addCommand(root, newLeafCmd("acts"), groupSetup)
			root.SetArgs(tc.args)
			root.SetOut(&strings.Builder{})
			root.SetErr(&strings.Builder{})

			err := root.Execute()

			if tc.wantErr == "" {
				require.NoError(t, err)
				return
			}
			require.Error(t, err)
			assert.Contains(t, err.Error(), tc.wantErr)
