// TestJSONRequestedTreatsAnUndeclaredFlagAsNotRequested pins the read helper's
// contract: asking a command with no JSON view is a truthful no, not a panic,
// so shared rendering helpers can ask unconditionally.
func TestJSONRequestedTreatsAnUndeclaredFlagAsNotRequested(t *testing.T) {
	t.Parallel()

	declared := newLeafCmd("declared")
	addJSONFlag(declared)
	require.False(t, jsonRequested(declared), "unset")
	require.NoError(t, declared.Flags().Set("json", "true"))
	assert.True(t, jsonRequested(declared), "set")

	assert.False(t, jsonRequested(newLeafCmd("undeclared")),
		"a command with no --json flag must answer no rather than panicking")
}

// TestHelpGroupsAreDeclaredInDisplayOrder holds the coupling addCommand relies
// on: groups are declared as commands are attached, so attaching out of
// helpGroups order would silently reorder the help output.
func TestHelpGroupsAreDeclaredInDisplayOrder(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()
	addCommand(root, newLeafCmd("setup-verb"), groupSetup)
	addCommand(root, newLeafCmd("asset-verb"), groupAssets)
	addCommand(root, newLeafCmd("another-asset-verb"), groupAssets)

	var got []string
	for _, g := range root.Groups() {
		got = append(got, g.ID)
	}
	assert.Equal(t, []string{groupSetup, groupAssets}, got,
		"a group is declared once, on first use, in the order commands are attached")

	titles := root.UsageString()
	assert.Less(t, strings.Index(titles, "Setup Commands:"), strings.Index(titles, "Asset Commands:"))
}

// TestNewRootCmdDeclaresNoUnusedHelpGroups keeps the help output honest while
// the command set is still being built: cobra prints a header for every
// declared group, so a group whose commands do not exist yet must stay
// undeclared rather than render as an empty heading.
func TestNewRootCmdDeclaresNoUnusedHelpGroups(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()
	for _, g := range root.Groups() {
		assert.True(t, groupHasMember(root, g.ID), "help group %q is declared but has no commands", g.ID)
	}
}

func groupHasMember(root *cobra.Command, groupID string) bool {
	for _, c := range root.Commands() {
		if c.GroupID == groupID {
			return true
		}
	}
	return false
}

// TestEveryCommandIsFiledUnderADeclaredGroup checks the invariant cobra itself
// panics over at execute time, at construction time instead.
func TestEveryCommandIsFiledUnderADeclaredGroup(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()
	for _, c := range root.Commands() {
		if c.GroupID == "" && (c.Name() == "help" || c.Name() == "completion") {
			continue // cobra's own generated commands are not ours to group
		}
		assert.True(t, root.ContainsGroup(c.GroupID), "command %q has undeclared group %q", c.Name(), c.GroupID)
	}
}

func TestAddCommandRejectsAnUnknownHelpGroup(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()
	assert.PanicsWithValue(t, `command "stray" filed under unknown help group "nowhere"`, func() {
		addCommand(root, newLeafCmd("stray"), "nowhere")
	})
}

// TestPackageDeclaresNoInit asserts by construction what task 3.2 asks for: no
// command registers itself from a package init, so NewRootCmd is the whole
// tree. The gochecknoinits linter says the same thing, but a lint rule can be
// suppressed with a comment and this cannot.
func TestPackageDeclaresNoInit(t *testing.T) {
	t.Parallel()

	fset := token.NewFileSet()
	pkgs, err := parser.ParseDir(fset, ".", func(fi os.FileInfo) bool {
		return !strings.HasSuffix(fi.Name(), "_test.go")
	}, 0)
	require.NoError(t, err)

	for _, pkg := range pkgs {
		for name, file := range pkg.Files {
			for _, decl := range file.Decls {
				fn, ok := decl.(*ast.FuncDecl)
				if !ok || fn.Recv != nil {
					continue
				}
				assert.NotEqual(t, "init", fn.Name.Name,
					"%s declares a package init; attach commands from NewRootCmd instead", name)
			}
		}
	}
}

